function pointForecast(field){const p=current()?.input.ignitions[0]?.point||[map.getCenter().lat,map.getCenter().lng],records=[];for(const r of field.records){const v=sampleVector(field,r,...p);if(!v)return null;records.push({at:r.at,values:{wind_speed_10m:Math.hypot(...v),wind_direction_10m:(Math.atan2(-v[0],-v[1])*180/Math.PI+360)%360,temperature_2m:sampleScalar(field,r,'temperature',...p),relative_humidity_2m:sampleScalar(field,r,'humidity',...p),precipitation:sampleScalar(field,r,'precipitation',...p),surface_pressure:sampleScalar(field,r,'pressure',...p),shortwave_radiation:sampleScalar(field,r,'radiation',...p)}});}return {...field,records};}
async function refresh(){try{const w=checkedForecastTime(await api('/api/weather/map'),10800);distributedForecast=w.forecast;forecast=distributedForecast?pointForecast(distributedForecast):null;forecastState=forecast?w.status:'UNAVAILABLE';if(forecast){const keep=current()?.input.start_at||$('start').value,rows=forecast.records.filter(r=>Date.parse(r.at)>Date.now());$('start').replaceChildren(...rows.map(r=>{const o=document.createElement('option');o.value=r.at;o.textContent=clock(r.at)+' Roma';return o;}));if(keep&&!rows.some(r=>r.at===keep)){const old=document.createElement('option');old.value=keep;old.textContent=clock(keep)+' Roma · inizio precedente, da aggiornare al calcolo';$('start').prepend(old);}if(keep)$('start').value=keep;if(current()?.input.weather_source==='FORECAST'&&!current().input.start_at)applyForecast();}const [health,research]=await Promise.all([api('/api/health'),api('/api/research')]);faults=research.faults;$('continuity').textContent='VM: '+health.status+' · meteo nella zona degli inneschi: '+forecastState+'. Ogni nuovo calcolo verifica e congela il campo distribuito nel dominio.';}catch(e){forecastState='UNAVAILABLE';$('continuity').textContent='Servizio temporaneamente indisponibile. Risultati caricati conservati.';}controls();renderWeather();}
function comparisonClock(){return [...new Set(scenarios.flatMap(s=>[...s.input.resources,...s.input.ignitions].map(i=>Math.floor(i.at_minutes*60))))].sort((a,b)=>a-b);}
async function run(s){if(s.pending)return;if(!s.input.ignitions.length)throw Error('Inserisci almeno un innesco comune prima del calcolo.');const body=clone(s.input);body.comparison_times=comparisonClock().filter(t=>t<body.hours*3600);if(body.weather_source==='FORECAST'){delete body.forcing_id;if(faults.includes('source_stale'))throw Error('Sorgente meteo indisponibile: nessuna previsione inventata.');body.moisture_model=s.input.moisture_model||'HFFMC_1977';s.input.moisture_model=body.moisture_model;if(runningQueue&&batchStartAt){body.start_at=batchStartAt;if(Date.parse(body.start_at)<=Date.now())throw Error('L’inizio comune del confronto è trascorso durante i calcoli: scegli una nuova partenza e ricalcola il gruppo.');}if(!body.start_at||Date.parse(body.start_at)<=Date.now()){body.start_at=new Date(Math.ceil((Date.now()+1000)/3600000)*3600000).toISOString().replace('.000Z','Z');s.input.start_at=body.start_at;loadControls();}if(runningQueue&&batchForecastId)body.forcing_id=batchForecastId;const v=await api('/api/firelab/dynamic',body);s.preparation_id=v.preparation_id;s.submitted_input=body;s.pending=true;s.error=null;scheduleSave();render();message(s.name+': preparo terreno, vegetazione e meteo attorno agli inneschi nella VM.');return;}
const v=await api('/api/firelab/scenario',body);if(s.job_id&&seriesCache.has(s.job_id))s.previous_job_id=s.job_id;s.job_id=v.jobs.B;s.submitted_input=body;s.pending=true;s.error=null;scheduleSave();render();message(s.name+': replay storico accodato nella VM.');}
$('cancel-run').onclick=async()=>{const s=current();if(!s?.pending)return;await api(s.preparation_id?'/api/fire-preparations/'+s.preparation_id+'/cancel':'/api/jobs/'+s.job_id+'/cancel',{});message('Annullamento richiesto per '+s.name);};
$('run').onclick=async()=>{try{await run(current());}catch(e){message(e.message,true);}};
$('run-all').onclick=async()=>{const group=scenarios.filter(s=>comparison.has(s.id));let start=current()?.input.start_at;if(!start||Date.parse(start)<=Date.now())start=new Date(Math.ceil((Date.now()+1000)/3600000)*3600000).toISOString().replace('.000Z','Z');for(const s of group)if(s.input.weather_source==='FORECAST')s.input.start_at=start;runQueue=group.map(s=>s.id);batchForecastId=null;batchStartAt=start;runningQueue=true;loadControls();scheduleSave();controls();await advanceQueue();};
async function advanceQueue(){if(!runningQueue||queueSubmitting||scenarios.some(s=>s.pending))return;if(!runQueue.length){runningQueue=false;controls();return;}const id=runQueue.shift(),s=scenarios.find(s=>s.id===id);if(!s){runQueue=[];runningQueue=false;controls();message('Uno scenario del confronto è stato rimosso: seleziona il gruppo da ricalcolare.',true);return;}queueSubmitting=true;try{await run(s);}catch(e){s.error=e.message;runQueue=[];runningQueue=false;render();message(e.message,true);}finally{queueSubmitting=false;}}
async function poll(){if(polling)return;polling=true;try{for(const s of scenarios.filter(s=>s.pending)){if(s.preparation_id){const preparation=await api('/api/fire-preparations/'+s.preparation_id);s.preparation_detail=preparation.detail;if(preparation.state==='SUCCEEDED'){if(s.job_id&&seriesCache.has(s.job_id))s.previous_job_id=s.job_id;s.job_id=preparation.jobs.B;delete s.preparation_id;delete s.preparation_detail;if(runningQueue&&!batchForecastId)batchForecastId=preparation.forcing_id;scheduleSave();render();}else if(['ERROR','CANCELLED'].includes(preparation.state)){s.pending=false;s.error=preparation.detail;delete s.preparation_id;scheduleSave();render();message(s.name+': '+s.error,true);continue;}else{render();continue;}}const v=await api('/api/firelab/'+s.job_id);if(v.state==='SUCCEEDED'){seriesCache.set(s.job_id,v.series);s.pending=false;s.error=null;scheduleSave();render();message(s.name+': risultato disponibile. Usa ▶ Riproduci o sposta il cursore.');}else if(['ERROR','CANCELLED','TIMEOUT'].includes(v.state)){s.pending=false;s.error=v.error_code||v.state;scheduleSave();render();message(s.name+': '+s.error+'. Gli altri scenari restano disponibili.',true);}}await advanceQueue();}catch(e){console.warn('Verifica calcoli scenari',e);message('Verifica calcoli temporaneamente non disponibile. I job restano identificati; riprovo.',true);}finally{polling=false;}}
function inputFromSeries(r){const p=r.plan;return {ignitions:clone(p.ignitions_wgs84||[{id:uid('fire'),point:p.ignition_wgs84,at_minutes:0}]),hours:resultHours(r),seed:r.options?.seed??1729,moisture_percent:p.moisture_percent,resources:clone(p.resources),weather_source:p.weather_source,weather_changes:clone(p.weather_changes),...(p.weather_source==='FORECAST'?{start_at:r.valid_from}:{} )};}
function showCase(info){if(!info)return;const banner=document.createElement('aside');banner.className='case-banner';banner.setAttribute('aria-label','Prova salvata separata');const title=document.createElement('strong'),description=document.createElement('p'),back=document.createElement('a');title.textContent=info.title;description.textContent=info.description+' Le modifiche restano separate dai tuoi scenari.';back.textContent='Torna ai miei scenari';back.href='/?view=results';back.target='_top';banner.append(title,description,back);board.prepend(banner);}
async function caseLibrary(){try{const value=await api('/api/fire-cases');if(!value.cases?.length)return;const section=document.createElement('div'),title=document.createElement('strong');title.textContent='Prove salvate · apri senza sostituire i tuoi scenari';section.append(title);for(const c of value.cases){const p=document.createElement('p'),link=document.createElement('a');link.textContent=c.title;link.href='/?view=results&case='+encodeURIComponent(c.id);link.target='_top';p.append(link);section.append(p);}document.querySelector('.workflow-guide').append(section);}catch(e){console.warn('Catalogo prove non disponibile',e);}}
async function init(){try{const saved=await api('/api/fire-workspace'),needsInitialSave=!saved.scenarios.length;showCase(saved.case);void caseLibrary();revision=saved.revision;scenarios=saved.scenarios;$('save-status').textContent=saved.scenarios.length?'Configurazioni salvate nella VM':'';for(const s of scenarios){comparison.add(s.id);if(s.preparation_id)s.pending=true;if(s.previous_job_id){try{const v=await api('/api/firelab/'+s.previous_job_id);if(v.state==='SUCCEEDED')seriesCache.set(s.previous_job_id,v.series);}catch(e){}}if(s.job_id){try{const v=await api('/api/firelab/'+s.job_id);if(v.state==='SUCCEEDED')seriesCache.set(s.job_id,v.series);else if(!s.preparation_id){s.pending=!['ERROR','CANCELLED','TIMEOUT'].includes(v.state);if(!s.pending)s.error=v.error_code||v.state;}}catch(e){s.error=e.message;}}}if(saved.case)hour=saved.case.initial_hour||0;if(!scenarios.length)newScenario('Senza interventi',defaultInput());selectedId=scenarios[0].id;loadControls();render();$('fit').click();await refresh();if(needsInitialSave)scheduleSave();await poll();}catch(e){message('Caricamento configurazioni non riuscito: '+e.message,true);}}
window.addEventListener('message',e=>{if(e.origin===location.origin&&e.source===window.parent&&e.data?.type==='hazardia-studio-visible')map.invalidateSize({pan:false});});
if(window.parent!==window){let lastHeight=0;new ResizeObserver(()=>{const height=Math.ceil(document.body.getBoundingClientRect().height);if(height!==lastHeight){lastHeight=height;window.parent.postMessage({type:'hazardia-studio-height',height},location.origin);}}).observe(document.body);}
init();setInterval(refresh,30000);setInterval(poll,1500);
